import numpy as np

def select_next_node(current_node, depot, unvisited_nodes, rest_capacity, demands, distance_matrix):
    """Return an int from unvisited_nodes (or 0 to return to depot early when current_node != 0)."""
    uv = np.asarray(unvisited_nodes, dtype=np.int64)
    if uv.size == 0:
        return int(depot)

    scale = float(np.mean(distance_matrix[depot, 1:]))
    if not np.isfinite(scale) or scale <= 0.0:
        scale = 1.0

    d_cur = distance_matrix[current_node, uv].astype(np.float64) / scale
    d0 = distance_matrix[depot, uv].astype(np.float64) / scale
    dem = np.asarray(demands, dtype=np.float64)[uv] / scale

    savings = d0 - d_cur
    nearest_idx = int(np.argmin(d_cur))
    nearest_dist = float(d_cur[nearest_idx])
    nearest_dem = float(dem[nearest_idx])

    fill = float(rest_capacity) / scale
    load_frac = float(rest_capacity) / max(float(rest_capacity) + float(np.sum(dem)), 1e-12)

    if current_node != depot:
        if nearest_dem > 0.0 and (float(rest_capacity) / max(float(demands[int(uv[nearest_idx])]), 1e-12)) < 1.02:
            return int(depot)
        if nearest_dist > 0.90 and fill < 0.50:
            return int(depot)
        if load_frac < 0.18 and nearest_dist > 0.70:
            return int(depot)

    w_save = 0.75 * (1.0 - load_frac) + 0.10
    w_near = 1.0 - w_save
    score = w_save * savings - w_near * d_cur
    best = int(np.argmax(score))
    return int(uv[best])
